// Worker entry: the Next.js app (built by OpenNext) plus a Cron Trigger handler.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the file only exists after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent until the first build)
import { default as app } from "./.open-next/worker.js";

const HOURLY_SWEEP_CRON = "7 * * * *";

export default {
  fetch: app.fetch,

  // Cron Triggers call the app's own tick endpoint in-process (no network hop),
  // so engagement logic runs with the same request context as everything else.
  async scheduled(event, env, ctx) {
    const sweep = event.cron === HOURLY_SWEEP_CRON ? "?sweep=1" : "";
    const request = new Request(`${env.APP_URL ?? "https://pofu.internal"}/api/cron/tick${sweep}`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? env.AUTH_SECRET}` },
    });
    const res: Response = await app.fetch(request, env, ctx);
    if (!res.ok) throw new Error(`cron tick failed: ${res.status} ${await res.text()}`);
    console.log("[cron]", event.cron, await res.text());
  },
} satisfies ExportedHandler<CloudflareEnv>;
